DROP TABLE IF EXISTS `incentive_quality_ratios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `incentive_quality_ratios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `team_id` int NOT NULL,
  `ratio_type` varchar(50) NOT NULL,
  `ratio_value` decimal(5,4) NOT NULL,
  `period_date` date NOT NULL,
  `version_id` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_team_ratio_period` (`team_id`,`ratio_type`,`period_date`,`version_id`),
  KEY `idx_team_version` (`team_id`,`version_id`),
  KEY `version_id` (`version_id`),
  CONSTRAINT `incentive_quality_ratios_ibfk_1` FOREIGN KEY (`version_id`) REFERENCES `forecast_versions` (`version_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8051 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
