DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `can_user_edit_forecast`(
    p_user_email VARCHAR(100),
    p_team_id INT,
    p_version_id INT,
    p_period_date DATE
) RETURNS tinyint(1)
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE v_can_edit BOOLEAN DEFAULT FALSE;
    DECLARE v_permission VARCHAR(10);
    DECLARE v_version_locked BOOLEAN;
    DECLARE v_period_locked INT;
    
    -- Check if version is locked
    SELECT is_locked INTO v_version_locked
    FROM forecast_versions
    WHERE version_id = p_version_id;
    
    IF v_version_locked THEN
        RETURN FALSE;
    END IF;
    
    -- Check if period is locked
    SELECT COUNT(*) INTO v_period_locked
    FROM forecast_locks
    WHERE version_id = p_version_id
        AND (team_id IS NULL OR team_id = p_team_id)
        AND p_period_date BETWEEN period_start AND period_end;
    
    IF v_period_locked > 0 THEN
        RETURN FALSE;
    END IF;
    
    -- Check user permissions
    SELECT permission_type INTO v_permission
    FROM forecast_permissions
    WHERE user_email = p_user_email
        AND (team_id IS NULL OR team_id = p_team_id)
    ORDER BY 
        CASE 
            WHEN team_id IS NULL THEN 1 
            ELSE 0 
        END,
        CASE permission_type
            WHEN 'admin' THEN 1
            WHEN 'write' THEN 2
            WHEN 'read' THEN 3
        END
    LIMIT 1;
    
    IF v_permission IN ('write', 'admin') THEN
        SET v_can_edit = TRUE;
    END IF;
    
    RETURN v_can_edit;
END ;;
DELIMITER ;
