                (v_team_id, 'ar_enroll', 0.05, v_period_date, 2),
                (v_team_id, 'ar_book', 0.05, v_period_date, 2),
                (v_team_id, 'ar_ramp', 0.05, v_period_date, 2);
        END CASE;
        
    END LOOP;
    
    CLOSE cur;
END ;;
