CREATE DEFINER=`root`@`localhost` PROCEDURE `populate_quality_ratios_simple`()
BEGIN
    -- This inserts default ratios for any new teams
    INSERT IGNORE INTO incentive_quality_ratios (
        team_id, investment_accounts_ratio, banking_accounts_ratio, wealth_overlay_ratio,
        investment_assets_ratio, banking_assets_ratio, wealth_assets_ratio,
        headcount_ratio, ar_enroll_ratio, ar_book_ratio, ar_ramp_ratio, created_by
    )
    SELECT 
        t.team_id,
        0.90, 0.90, 0.05, 0.90, 0.90, 0.05, 0.90, 0.05, 0.05, 0.05, 'system'
    FROM mock_actuals_database.teams_reference t
    LEFT JOIN incentive_quality_ratios r ON t.team_id = r.team_id
    WHERE t.is_active = TRUE
      AND r.team_id IS NULL;
END ;;
DELIMITER ;
